"""Range family: buy a close 2.0 deviations under its 72-candle mean while BTC is flat (within 5% of its 200-day mean), sell back at z 0.0."""

from datetime import timedelta

from pandas import DataFrame

from freqtrade.strategy import IStrategy, merge_informative_pair
from lab import channels, metrics


class RangeZ72_4h(IStrategy):
    INTERFACE_VERSION = 3
    timeframe = "4h"
    can_short = False
    startup_candle_count = 200
    minimal_roi = {"0": 0.1}
    stoploss = -0.1
    max_hold = timedelta(hours=192.0)

    def btc(self) -> str:
        return f"BTC/{self.config['stake_currency']}"

    def informative_pairs(self):
        return [(self.btc(), "1d")]

    def populate_indicators(self, dataframe: DataFrame, metadata: dict) -> DataFrame:
        btc = self.dp.get_pair_dataframe(self.btc(), "1d")[["date", "close"]]
        btc["flat"] = metrics.trend_buckets(btc["close"], 0.05).eq("flat")
        dataframe = merge_informative_pair(dataframe, btc[["date", "flat"]], self.timeframe, "1d", ffill=True)
        dataframe["flat"] = dataframe["flat_1d"].eq(True)
        dataframe["z"] = channels.zscore(dataframe["close"], 72)
        return dataframe

    def populate_entry_trend(self, dataframe: DataFrame, metadata: dict) -> DataFrame:
        dataframe.loc[dataframe["flat"] & (dataframe["z"] <= -2.0) & (dataframe["volume"] > 0), "enter_long"] = 1
        return dataframe

    def populate_exit_trend(self, dataframe: DataFrame, metadata: dict) -> DataFrame:
        dataframe.loc[dataframe["z"] >= 0.0, "exit_long"] = 1
        return dataframe

    def custom_exit(self, pair: str, trade, current_time, current_rate, current_profit, **kwargs):
        if current_time - trade.open_date_utc >= self.max_hold:
            return "time_stop"
        return None
